begin;
with j as (select * from jsonb_to_recordset($law7d0009$[{"code_id":"APK_RF","article_number":"225.15","version_date":"2002-07-24","article_text":"1. Замена лица, которое ведет дело в интересах группы лиц, допускается в случае прекращения его полномочий по основаниям, предусмотренным частью 4 статьи 22510-1 настоящего Кодекса.\n\n2. В случае поступления в арбитражный суд заявления лица, которое ведет дело в интересах группы лиц, об отказе от иска арбитражный суд выносит определение об отложении судебного разбирательства и устанавливает срок, который не превышает двух месяцев со дня вынесения определения и в течение которого должна быть произведена замена указанного лица другим лицом.\n\n3. В определении об отложении судебного разбирательства арбитражный суд указывает на обязанность лица, которое ведет дело в интересах группы лиц, уведомить о своем отказе от иска лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, и определяет форму их уведомления с учетом положений, предусмотренных статьей 22514 настоящего Кодекса. Уведомление также должно содержать указание на необходимость замены лица, которое ведет дело в интересах группы лиц, другим лицом и информацию о последствиях, предусмотренных частью 7 настоящей статьи. Доказательства уведомления об отказе от иска направляются лицом, которое ведет дело в интересах группы лиц, в арбитражный суд.\n\n4. В арбитражный суд в течение срока, установленного в определении арбитражного суда, должны быть представлены доказательства, подтверждающие произведенную замену лица, которое ведет дело в интересах группы лиц.\n\n5. Арбитражный суд не принимает отказ от иска, если на момент истечения срока, установленного в определении суда, не располагает сведениями об уведомлении лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, и о замене лица, которое ведет дело в интересах группы лиц.\n\n6. О прекращении производства по делу в отношении лица, которое ведет дело в интересах группы лиц, и о замене его другим лицом арбитражный суд выносит определение.\n\n7. В случае, если лицо, которое ведет дело в интересах группы лиц, подавшее заявление об отказе от иска, выполнит все необходимые действия по уведомлению лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, но указанные лица в течение установленного арбитражным судом срока не произведут замену такого лица другим лицом, арбитражный суд принимает отказ от иска и прекращает производство по делу о защите прав и законных интересов группы лиц в порядке, установленном статьей 151 настоящего Кодекса. Прекращение производства по делу о защите прав и законных интересов группы лиц не лишает лиц из этой группы права обратиться в арбитражный суд за защитой своих нарушенных или оспариваемых прав и законных интересов в порядке, установленном настоящим Кодексом.\n\n8. В случае обращения большинства лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, с ходатайством о замене лица, которое ведет дело в интересах группы лиц, другим лицом по основанию, предусмотренному пунктом 2 части 4 статьи 22510-1 настоящего Кодекса, в таком обращении должна быть указана кандидатура другого лица. В случае удовлетворения данного ходатайства арбитражный суд заменяет лицо, которое ведет дело в интересах группы лиц, и выносит соответствующее определение.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.15. Замена лица, которое ведет дело в интересах группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"62dc5871250d319cf3c88dd8087cd0999c80be3e408b37ca067c83c2a31f75b9"},{"code_id":"APK_RF","article_number":"225.16","version_date":"2002-07-24","article_text":"1. Дела о защите прав и законных интересов группы лиц рассматриваются арбитражными судами по правилам, установленным настоящим Кодексом, с особенностями, предусмотренными настоящей главой.\n\n2. Дело о защите прав и законных интересов группы лиц рассматривается арбитражным судом в срок, не превышающий восьми месяцев со дня вынесения определения о принятии искового заявления, заявления, поданных в защиту прав и законных интересов группы лиц, к производству арбитражного суда, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу.\n\n3. В случае обращения в арбитражный суд лица, являющегося членом группы лиц, но не присоединившегося к требованию о защите прав и законных интересов данной группы лиц, с самостоятельным иском (далее в настоящей статье - лицо, обратившееся с самостоятельным иском) к тому же ответчику и о том же предмете арбитражный суд разъясняет лицу, обратившемуся с самостоятельным иском, право присоединиться к требованию о защите прав и законных интересов группы лиц в порядке, установленном статьей 22510 настоящего Кодекса.\n\n4. Если лицо, обратившееся с самостоятельным иском, присоединяется к требованию о защите прав и законных интересов группы лиц, ар\n\nбитражный суд выносит определение о присоединении данного лица к требованию о защите прав и законных интересов группы лиц. При этом арбитражный суд, в который обратилось указанное лицо, выносит определение о передаче материалов дела в арбитражный суд, который рассматривает дело о защите прав и законных интересов группы лиц.\n\n5. Если лицо, обратившееся с самостоятельным иском, не воспользуется правом присоединиться к требованию о защите прав и законных интересов группы лиц, арбитражный суд приостанавливает производство по делу указанного лица до вступления в законную силу решения суда по делу о защите прав и законных интересов группы лиц.\n\n6. Производство по делу лица, обратившегося с самостоятельным иском, приостанавливается в том числе в случае, если исковое заявление, заявление, поданные в защиту прав и законных интересов группы лиц, предъявлены позднее обращения в арбитражный суд указанного лица.\n\n7. Арбитражный суд прекращает производство по делу, если установит, что имеется принятое по требованию о защите прав и законных интересов группы лиц и вступившее в законную силу решение арбитражного суда и исковое заявление, заявление поданы лицом, отказавшимся от заявления о присоединении к требованию о защите прав и законных интересов группы лиц либо не воспользовавшимся правом присоединиться к данному требованию или вступить самостоятельно в дело на стороне истца или в качестве третьего лица, заявляющего самостоятельные требования относительно предмета спора, к тому же ответчику и о том же предмете, за исключением случаев, если арбитражный суд признает причины обращения указанного лица с самостоятельными исковым заявлением, заявлением уважительными.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.16. Порядок рассмотрения дел о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93b181686363e4f0ad66721849b345032fbed7d8107bbc42be382137216261ae"},{"code_id":"APK_RF","article_number":"225.16-1","version_date":"2002-07-24","article_text":"1. Лицо, которое ведет дело в интересах группы лиц, и лицо (лица), присоединившееся к требованию о защите прав и законных интересов группы лиц, вправе заключить в нотариальной форме соглашение, которое определяет порядок несения его сторонами судебных расходов (соглашение группы лиц). Требования об изменении и о расторжении соглашения группы лиц могут быть предъявлены только в суд, который рассматривает дело о защите прав и законных интересов группы лиц.\n\n2. В случае заключения группой лиц соглашения, указанного в части 1 настоящей статьи, суд после распределения судебных расходов по правилам, установленным главой 9 настоящего Кодекса, решает вопрос об отнесении на лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, судебных расходов в соответствии с заключенным между ними соглашением либо, если решение по делу о защите прав и законных интересов группы лиц принято в пользу группы лиц, о взыскании судебных расходов в пользу лиц, присоединившихся к требованию о защите прав и законных интересов группы лиц, которые понесли эти расходы в соответствии с условиями такого соглашения.\n\n(Дополнение статьей - Федеральный закон от 18.07.2019 № 191-ФЗ)","article_title":"Статья 225.16-1. Порядок несения судебных расходов по делу о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ec71a821aa4a106a5b53a4425aff7d351491498a812902e2218c2ef7b5d7320f"},{"code_id":"APK_RF","article_number":"225.17","version_date":"2002-07-24","article_text":"1. Решение по делу о защите прав и законных интересов группы лиц принимается по правилам, установленным главой 20 настоящего Кодекса.\n\n2. Обстоятельства, установленные вступившим в законную силу решением арбитражного суда по ранее рассмотренному делу о защите прав и законных интересов группы лиц, не доказываются вновь при рассмотрении арбитражным судом другого дела по заявлению члена этой группы лиц, который ранее не присоединился либо отказался от заявления о присоединении к требованию о защите прав и законных интересов группы лиц, предъявленному к тому же ответчику и о том же предмете, за исключением случаев, если указанные обстоятельства оспариваются этим членом группы лиц.\n\n3. В решении по делу о защите прав и законных интересов группы лиц, принятом в пользу группы лиц, арбитражный суд может указать на обязанность ответчика довести информацию о принятом решении до сведения всех членов группы лиц в установленный арбитражным судом срок через средства массовой информации или иным способом.\n\n4. В резолютивной части решения по делу о защите прав и законных интересов группы лиц должны содержаться выводы в отношении каждого из членов группы, присоединившихся к требованию о защите прав и законных интересов группы лиц.\n\n(Статья в редакции Федерального закона от 18.07.2019 № 191-ФЗ)\n\n(Глава в редакции Федерального закона от 25.06.2012 № 86-ФЗ)","article_title":"Статья 225.17. Решение арбитражного суда по делу о защите прав и законных интересов группы лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aca6ebba0029c553f440891771c3b90507e144558472b3456b47ccc4ab1339a3"},{"code_id":"APK_RF","article_number":"225.2","version_date":"2002-07-24","article_text":"1. Дела по корпоративным спорам рассматриваются арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой.\n\n2. При рассмотрении дел, предусмотренных пунктом 5 статьи 2251 настоящего Кодекса и связанных с оспариванием ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, должностных лиц, применяются также особенности, установленные главой 24 настоящего Кодекса.","article_title":"Статья 225.2. Порядок рассмотрения дел по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"564690ef6b20c4ec8133a60097b008d3f63f016d6c01a409f15971afe38ce487"},{"code_id":"APK_RF","article_number":"225.3","version_date":"2002-07-24","article_text":"1. Исковое заявление, заявление по корпоративному спору должны соответствовать требованиям, которые предусмотрены статьей 125 настоящего Кодекса. В исковом заявлении, заявлении должны быть также указаны:\n\n1) государственный регистрационный номер юридического лица, указанного в статье 2251 настоящего Кодекса;\n\n2) содержащийся в едином государственном реестре юридических лиц адрес (место нахождения) юридического лица, указанного в статье 2251 настоящего Кодекса.\n\n2. К исковому заявлению, заявлению прилагаются документы, предусмотренные статьей 126 настоящего Кодекса, а также выписка из единого государственного реестра юридических лиц или иной документ, подтверждающий государственную регистрацию юридического лица и содержащий сведения о его адресе (месте нахождения) и государственном регистрационном номере.","article_title":"Статья 225.3. Требования к исковому заявлению, заявлению по корпоративному спору","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20bd1671226079b6091bde816d4a6fe263d0953d7e91b0fa5d1455198fe1cb31"},{"code_id":"APK_RF","article_number":"225.5","version_date":"2002-07-24","article_text":"1. Корпоративные споры могут быть урегулированы сторонами по правилам, установленным главой 15 настоящего Кодекса, путем заключения мирового соглашения или использования других примирительных процедур, в том числе при содействии посредника, если иное не установлено федеральным законом.\n\n2. Арбитражный суд не принимает отказ истца от иска, признание иска ответчиком, не утверждает мировое соглашение сторон в случаях, если это противоречит закону либо нарушает права и (или) законные интересы других лиц, в том числе юридического лица, указанного в статье 2251 настоящего Кодекса.","article_title":"Статья 225.5. Примирение сторон корпоративных споров","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"810af13293bcd0c44aba12a627c166f81bffaf638f2a31db0c08bf5b574ae124"},{"code_id":"APK_RF","article_number":"225.6","version_date":"2002-07-24","article_text":"1. Обеспечительные меры по корпоративным спорам принимаются арбитражным судом при наличии оснований, предусмотренных статьей 90 настоящего Кодекса. При этом принятие обеспечительных мер не должно приводить к фактической невозможности осуществлять юридическим лицом, указанным в статье 2251 настоящего Кодекса, деятельность или к существенному затруднению осуществления им деятельности, а также к нарушению этим юридическим лицом законодательства Российской Федерации.\n\n2. Обеспечительные меры по корпоративным спорам принимаются арбитражным судом в порядке, предусмотренном главой 8 настоящего Кодекса, с особенностями, установленными настоящей статьей.\n\n3. Обеспечительными мерами по корпоративным спорам могут быть, в частности:\n\n1) наложение ареста на акции, доли в уставном (складочном) капитале хозяйственных обществ и товариществ, паи членов кооперативов;\n\n2) запрещение ответчику и другим лицам совершать сделки и другие действия в отношении акций, долей в уставном (складочном) капитале хозяйственных обществ и товариществ, паев членов кооперативов;\n\n3) запрещение органам юридического лица принимать решения либо совершать иные действия по вопросам, относящимся к предмету спора или непосредственно с ним связанным;\n\n4) запрещение юридическому лицу, его органам или участникам, а также иным лицам исполнять решения, принятые органами этого юридического лица;\n\n5) запрещение держателю реестра владельцев ценных бумаг и (или) депозитарию осуществлять записи по учету или переходу прав на акции и иные ценные бумаги, а также совершать другие действия в связи с размещением и (или) обращением ценных бумаг.\n\n4. Арбитражным судом могут быть приняты иные обеспечительные меры по корпоративным спорам, в том числе одновременно несколько обеспечительных мер.\n\n5. При предоставлении встречного обеспечения его размер определяется в соответствии с частью 1 статьи 94 настоящего Кодекса.\n\n6. В случае, если требование истца носит неимущественный характер, размер встречного обеспечения определяется арбитражным судом исходя из размера возможных убытков ответчика, причиненных обеспечительными мерами, но для физических лиц не может быть менее чем пятьдесят тысяч рублей, для юридических лиц - сто тысяч рублей.\n\n7. В случае, если при рассмотрении заявления о принятии обеспечительных мер у арбитражного суда возникла необходимость заслушать объяснения лиц, участвующих в деле, и лицо, обратившееся с заявлением об обеспечении иска, не предоставило встречное обеспечение, предусмотренное частью 4 настоящей статьи, судья может назначить рассмотрение заявления об обеспечении иска в судебном заседании, которое должно быть проведено в срок, не превышающий пятнадцати дней со дня поступления такого заявления в арбитражный суд.\n\n8. Арбитражный суд не позднее следующего дня после дня поступления заявления об обеспечении иска в арбитражный суд выносит определение о принятии заявления к производству арбитражного суда, в котором указывает время и место судебного заседания. Такое определение не позднее следующего дня после дня его вынесения направляется лицам, участвующим в деле, в порядке, установленном частью 3 статьи 121 настоящего Кодекса.\n\n9. В определении о принятии заявления об обеспечении иска к производству арбитражный суд также может указать на обязанность лица, обратившегося с заявлением об обеспечении иска, уведомить лиц, участвующих в деле, и юридическое лицо, указанное в статье 2251 настоящего Кодекса, о времени и месте рассмотрения заявления об обеспечении иска.\n\n10. В случае неисполнения обязанности по уведомлению, предусмотренной частью 9 настоящей статьи, на лицо, обратившееся с заявлением об обеспечении иска, арбитражным судом может быть наложен судебный штраф в порядке и в размерах, которые установлены главой 11 настоящего Кодекса. В случае, если с заявлением об обеспечении иска обратилось юридическое лицо, судебный штраф налагается на лицо, осуществляющее функции единоличного исполнительного органа или возглавляющее коллегиальный исполнительный орган этого юридического лица.\n\n11. Арбитражный суд вправе рассмотреть заявление об обеспечении иска в отсутствие лиц, указанных в части 7 настоящей статьи, если к началу судебного заседания располагает сведениями об их уведомлении о времени и месте рассмотрения заявления об обеспечении иска или если лицом, ходатайствующим об обеспечении иска, представлены доказательства того, что им предприняты все зависящие от него необходимые меры по такому уведомлению.","article_title":"Статья 225.6. Обеспечительные меры арбитражного суда по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ea698a843f9df1fd9386913df68bad111882dc9a994a72d81d4f1e6254dabbc"},{"code_id":"APK_RF","article_number":"225.7","version_date":"2002-07-24","article_text":"1. В случаях, предусмотренных федеральным законом, органы юридического лица или его участники вправе обратиться в арбитражный суд с иском о понуждении юридического лица созвать общее собрание участников.\n\n2. Дела о понуждении юридического лица созвать общее собрание участников рассматриваются в срок, не превышающий одного месяца со дня поступления искового заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу.\n\n3. Решение арбитражного суда о понуждении юридического лица созвать общее собрание участников подлежит немедленному исполнению, если иные сроки не установлены в решении суда.\n\n4. Решение арбитражного суда о пону\n\nждении юридического лица созвать общее собрание участников может быть обжаловано в арбитражный суд апелляционной инстанции в течение десяти дней со дня принятия данного решения.\n\n5. Постановление арбитражного суда апелляционной инстанции по результатам рассмотрения апелляционной жалобы на решение о понуждении юридического лица созвать общее собрание участников может быть обжаловано в арбитражный суд кассационной инстанции в течение десяти дней со дня принятия данного решения.","article_title":"Статья 225.7. Рассмотрение дел о понуждении юридического лица созвать общее собрание участников","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36078ef1f03a9024272c76552d3b997c2f9e45b25a431e3e8c73f7d87f3aae20"},{"code_id":"APK_RF","article_number":"225.8","version_date":"2002-07-24","article_text":"1. В случаях, предусмотренных федеральным законом, участники юридического лица вправе обратиться в арбитражный суд с иском о возмещении убытков, причиненных этому юридическому лицу. Такие участники пользуются процессуальными правами и несут процессуальные обязанности истца, а также обладают правом требовать принудительное исполнение решения арбитражного суда в пользу этого юридического лица.\n\n2. Решение об удовлетворении требования по иску о возмещении убытков принимается в пользу юридического лица, в интересах которого был предъявлен иск. По ходатайству лица, обратившегося с иском о возмещении убытков, исполнительный лист направляется для исполнения непосредственно арбитражным судом.\n\n3. Судебные расходы, связанные с рассмотрением дела по иску участников юридического лица о возмещении убытков, причиненных юридическому лицу, несут такие участники в равных долях.\n\n4. Возмещение судебных расходов производится по правилам, установленным статьей 110 настоящего Кодекса.","article_title":"Статья 225.8. Рассмотрение дел по спорам о возмещении убытков, причиненных юридическому лицу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2cdbad25feb9c310a81ffdd3eec9231a6e64904a2acbfc79cb1171fe16490c59"},{"code_id":"APK_RF","article_number":"225.9","version_date":"2002-07-24","article_text":"1. Определения арбитражного суда, выносимые при рассмотрении дел по корпоративным спорам, обжалуются по правилам, установленным статьей 188 настоящего Кодекса. Жалобы на такие определения, за исключением определений о прекращении производства по делу и об оставлении заявления без рассмотрения, подаются в арбитражный суд апелляционной инстанции в течение десяти дней со дня их вынесения.\n\n2. Подача жалобы на указанные в части 1 настоящей статьи определения не препятствует рассмотрению дела арбитражным судом и совершению отдельных процессуальных действий по делу.\n\n(Дополнение главой - Федеральный закон от 19.07.2009 № 205-ФЗ)","article_title":"Статья 225.9. Особенности обжалования определений арбитражного суда по корпоративным спорам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5507e79d80191afd852e9257ef23ffc51fcc1d2247af0665b52a3389d870b0cc"},{"code_id":"APK_RF","article_number":"226","version_date":"2002-07-24","article_text":"1. Дела в порядке упрощенного производства рассматриваются арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой.\n\nПри рассмотрении в порядке упрощенного производства дел, возникающих из административных и иных публичных правоотношений, применяются также особенности, установленные разделом III настоящего Кодекса, при рассмотрении дел с участием иностранных лиц - разделом V настоящего Кодекса, если иное не предусмотрено настоящей главой.\n\nСрок рассмотрения дела в порядке упрощенного производства продлению не подлежит, за исключением случая, предусмотренного частью 3 статьи 253 настоящего Кодекса.","article_title":"Статья 226. Порядок упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fc15ddb78c30563116c67bd061e1f40e11c2f44bdefad0a0db1939469634b2a4"},{"code_id":"APK_RF","article_number":"227","version_date":"2002-07-24","article_text":"1. В порядке упрощенного производства подлежат рассмотрению дела:\n\n1) по исковым заявлениям о взыскании денежных средств, если цена иска не превышает для юридических лиц один миллион двести тысяч рублей, для индивидуальных предпринимателей - шестьсот тысяч рублей; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n2) об оспаривании ненормативных правовых актов, решений органов, осуществляющих публичные полномочия, должностных лиц, если в соответствующих ненормативном правовом акте, решении содержится требование об уплате денежных средств или предусмотрено взыскание денежных средств либо обращение взыскания на иное имущество заявителя при условии, что указанные акты, решения оспариваются заявителем в части требования об уплате денежных средств или взыскания денежных средств либо обращения взыскания на иное имущество заявителя и при этом оспариваемая заявителем сумма не превышает сто тысяч рублей;\n\n3) о привлечении к административной ответственности, если за совершение административного правонарушения законом установлено административное наказание в виде предупреждения или административного штрафа, максимальный размер которого не превышает сто тысяч рублей;\n\n4) об оспаривании решений административных органов о привлечении к административной ответственности, если за совершение административного правонарушения назначено административное наказание в виде предупреждения или административного штрафа, размер которого не превышает сто тысяч рублей;\n\n5) о взыскании обязательных платежей и санкций, если указанный в заявлении общий размер подлежащей взысканию денежной суммы не превышает двести тысяч рублей, за исключением дел, рассматриваемых в порядке приказного производства.\n\n2. В порядке упрощенного производства независимо от цены иска подлежат рассмотрению дела:\n\n1) по искам, основанным на представленных истцом документах, устанавливающих денежные обязательства ответчика, которые ответчиком признаются, но не исполняются, и (или) на документах, подтверждающих задолженность по договору, за исключением дел, рассматриваемых в порядке приказного производства;\n\n2) по требованиям, основанным на совершенном нотариусом протесте векселя в неплатеже, неакцепте и недатировании акцепта, за исключением дел, рассматриваемых в порядке приказного производства;\n\n3) по требованиям о взыскании взносов, подлежащих уплате членами некоммерческих организаций, указанных в части 1 статьи 2251 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n3. По ходатайству истца при согласии ответчика или по инициативе суда при согласии сторон в порядке упрощенного производства могут быть рассмотрены также иные дела, если не имеется обстоятельств, указанных в части 5 настоящей статьи.\n\n1) порядок упрощенного производства может привести к разглашению государственной тайны;\n\n2) необходимо выяснить дополнительные обстоятельства или исследовать дополнительные доказательства, а также провести осмотр и исследование доказательств по месту их нахождения, назначить экспертизу или заслушать свидетельские показания;\n\n3) заявленное требование связано с иными требованиями, в том числе к другим лицам, или судебным актом, принятым по данному делу, могут быть нарушены права и законные интересы других лиц.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 227. Дела, рассматриваемые в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36b5e2be5457d0c561120aa6ca788707984243ef6f654a8a9c378ed68ad66a51"},{"code_id":"APK_RF","article_number":"228","version_date":"2002-07-24","article_text":"В определении суд может предложить сторонам урегулировать спор самостоятельно, указав на возможность примирения.\n\nОпределение, вынесенное арбитражным судом по результатам рассмотрения вопроса о принятии искового заявления, заявления, размещается в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее следующего дня после дня вынесения этого определения. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nСтороны вправе представить в арбитражный суд, рассматривающий дело, и направить друг другу дополнительно документы, содержащие объяснения по существу заявленных требований и возражений в обоснование своей позиции, в срок, который установлен арбитражным судом и не может составлять менее чем тридцать дней со дня вынесения определения о принятии искового заявления, заявления к производству или определения о переходе к рассмотрению дела в порядке упрощенного производства. Такие документы не должны содержать ссылки на доказательства, которые не были раскрыты в установленный судом срок.\n\nПоступившие в арбитражный суд отзыв на исковое заявление, отзыв на заявление, доказательства и иные документы размещаются в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа в срок, не превышающий трех дней со дня их поступления в арбитражный суд. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nПредварительное судебное заседание по делам, рассматриваемым в порядке упрощенного производства, не проводится.\n\nСуд исследует изложенные в представленных сторонами документах объяснения, возражения и (или) доводы лиц, участвующих в деле, и принимает решение на основании доказательств, представленных в течение указанных сроков.\n\nС учетом характера и сложности дела арбитражный суд вправе по своей инициативе или по ходатайству лиц, участвующих в деле, провести судебное заседание с вызовом лиц, участвующих в деле, без перехода к рассмотрению дела по общим правилам искового производства или по правилам административного судопроизводства. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)","article_title":"Статья 228. Особенности рассмотрения дел в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0f2961584281e7819ecf3a2c96e649d1f07c60337e69dac43f7899f1e5e3749"}]$law7d0009$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
